<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\Database;use App\Core\Request;
final class ApprovalWorkflowController extends BaseController {
 public function index(Request $r):void{$this->auth();$this->require('settings.manage');$pdo=Database::connection();$rows=$pdo->query('SELECT w.*,COUNT(s.id) step_count FROM approval_workflows w LEFT JOIN approval_steps s ON s.workflow_id=w.id GROUP BY w.id ORDER BY w.id DESC')->fetchAll();$roles=$pdo->query('SELECT id,name FROM roles WHERE is_active=1 ORDER BY name')->fetchAll();$this->view('approvals/workflows',['rows'=>$rows,'roles'=>$roles,'flash'=>flash('success'),'error'=>flash('error')]);}
 public function store(Request $r):void{$this->auth();$this->csrf();$this->require('settings.manage');$name=trim((string)$r->input('workflow_name'));$type=(string)$r->input('document_type');$step=trim((string)$r->input('step_name'));$role=(int)$r->input('approver_role_id');$order=max(1,(int)$r->input('step_order',1));$allowed=['purchase_request','requisition','quotation_comparison','purchase_order','invoice','payment'];if($name===''||$step===''||!in_array($type,$allowed,true)||$role<1){flash('error','Complete the workflow and approver details.');redirect('/approval-workflows');}$pdo=Database::connection();try{$pdo->beginTransaction();$pdo->prepare('INSERT INTO approval_workflows(workflow_name,document_type,branch_id,department_id,min_amount,max_amount,currency_code,is_active) VALUES(?,?,?,?,?,?,?,1)')->execute([$name,$type,$r->input('branch_id')?:null,$r->input('department_id')?:null,$r->input('min_amount')?:null,$r->input('max_amount')?:null,$r->input('currency_code')?:null]);$wid=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO approval_steps(workflow_id,step_order,approver_role_id,approval_mode,step_name) VALUES(?,?,?,'any',?)")->execute([$wid,$order,$role,$step]);$pdo->commit();\audit_log('approval_workflow_created','approval_workflows',$wid);flash('success','Approval workflow and first step saved. Add additional steps with the same workflow ID using the database or next workflow editor.');}catch(\Throwable $e){$pdo->rollBack();flash('error',$e->getMessage());}redirect('/approval-workflows');}
}
